  const assessmentItems=[{skill:'reading',prompt:'A teacher noticed that some students needed more time to organise their ideas. She introduced planning cards before writing. After two weeks, more students completed their paragraphs and used clearer examples.',question:'What was the purpose of the planning cards?',options:['To help students organise ideas before writing','To make students write longer homework','To replace classroom discussion'],answer:0},{skill:'reading',prompt:'A teacher noticed that some students needed more time to organise their ideas. She introduced planning cards before writing. After two weeks, more students completed their paragraphs and used clearer examples.',question:'What changed after two weeks?',options:['Students stopped asking questions','More students completed paragraphs with clearer examples','The teacher removed writing activities'],answer:1},{skill:'listening',audio:'Could you send me the revised lesson plan by Thursday afternoon?',question:'When should the revised lesson plan be sent?',options:['By Thursday afternoon','On Friday morning','Before Wednesday'],answer:0},{skill:'listening',audio:'Although the new routine takes a little longer, students are becoming more independent.',question:'What is the speaker’s main point?',options:['The routine is too difficult to continue','The routine takes longer but supports independence','Students prefer the old routine'],answer:1},{skill:'language',question:'Choose the most natural sentence for a professional update.',options:['I am writing to share an update on Maya’s progress.','I write you because Maya progress.','I am share update about progress Maya.'],answer:0},{skill:'language',question:'Complete the sentence: “If we give students clear steps, they ___ more confident.”',options:['will feel','felt yesterday','are feeling yesterday'],answer:0}];
