  async function pushProgress(){if(!currentUser||!supabaseClient||syncBusy)return;syncBusy=true;try{const stamp=new Date().toISOString();state._updatedAt=stamp;localStorage.setItem(accountStorageKey(),JSON.stringify(state));const {error}=await supabaseClient.from('learner_progress').upsert({user_id:currentUser.id,data:state,updated_at:stamp},{onConflict:'user_id'});if(error)throw error;setSyncStatus('☁️ Tersinkron','ok')}catch(error){setSyncStatus('⚠️ Belum tersinkron','error');console.error('Progress sync failed',error)}finally{syncBusy=false}}
  async function syncProgressFromCloud(initial=false){if(!currentUser||!supabaseClient||syncBusy)return;syncBusy=true;try{setSyncStatus('☁️ Menyinkronkan…','busy');const {data,error}=await supabaseClient.from('learner_progress').select('data,updated_at').eq('user_id',currentUser.id).maybeSingle();if(error)throw error;if(data?.data){const localTime=Date.parse(state._updatedAt||0),remoteTime=Date.parse(data.updated_at||data.data._updatedAt||0);if(localTime>remoteTime){syncBusy=false;await pushProgress();return}clearTimeout(syncTimer);state={...defaultState,...data.data,_updatedAt:data.updated_at||data.data._updatedAt};localStorage.setItem(accountStorageKey(),JSON.stringify(state));setSyncStatus('☁️ Tersinkron','ok');if(!initial)render()}else{syncBusy=false;await pushProgress();return}}catch(error){setSyncStatus('⚠️ Gagal sinkron','error');console.error('Progress sync failed',error)}finally{syncBusy=false}}
