  function studyDay(){let d=today();if(state.lastStudy!==d){let prev=new Date();prev.setDate(prev.getDate()-1);state.streak=state.lastStudy===prev.toISOString().slice(0,10)?(state.streak||0)+1:1;state.lastStudy=d}state.history.push({date:d,unit:current});state.history=state.history.slice(-80);save()}
  function scheduleReview(word,quality){state.reviews=state.reviews||{};const old=state.reviews[word]||{stage:0};if(quality<3){state.reviews[word]={stage:0,due:today(),lastQuality:quality};return}const stage=Math.min(4,(old.stage||0)+1),days=[1,3,7,14,30][Math.max(0,stage-1)];const due=new Date();due.setDate(due.getDate()+days);state.reviews[word]={stage,due:dateKey(due),lastQuality:quality};if(!state.learned.includes(word))state.learned.push(word)}
  function dueReviewWords(){return window.VOCABULARY.filter(w=>state.reviews?.[w.word]?.due&&state.reviews[w.word].due<=today())}
  function matchTextScore(target,heard){const a=target.toLowerCase().replace(/[^a-z\s']/g,'').trim().split(/\s+/),b=heard.toLowerCase().replace(/[^a-z\s']/g,'').trim().split(/\s+/);if(!a[0]||!b[0])return 0;const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const saved=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=saved}}return Math.max(0,Math.round((1-row[b.length]/Math.max(a.length,b.length))*100))}
  function startPronunciation(target){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){pronunciationResult={target,error:'Browser ini belum mendukung pengenalan suara. Coba gunakan Chrome atau Edge.'};practice();return}if(recognition){recognition.stop();recognition=null;return}pronunciationResult=null;recognition=new SpeechRecognition();recognition.lang='en-US';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onresult=event=>{const transcript=event.results?.[0]?.[0]?.transcript||'';pronunciationResult={target,transcript,score:matchTextScore(target,transcript)};recognition=null;practice()};recognition.onerror=event=>{const msg=event.error==='not-allowed'?'Izin mikrofon belum diberikan. Izinkan mikrofon di browser lalu coba lagi.':event.error==='no-speech'?'Belum terdengar suara. Coba bicara lebih dekat ke mikrofon.':'Tes suara gagal. Periksa mikrofon dan coba lagi.';pronunciationResult={target,error:msg};recognition=null;practice()};recognition.onend=()=>{recognition=null};try{recognition.start();toast('Silakan ucapkan kata setelah browser mulai mendengarkan 🎙️')}catch{recognition=null;pronunciationResult={target,error:'Tes suara belum bisa dimulai. Coba muat ulang halaman atau gunakan Chrome/Edge.'};practice()}}
