    function ensureCertificate(){if(!isAdmin()&&!state.certificate&&modules.every((_,i)=>state.completed.includes(i))){let serial='';try{const bytes=new Uint8Array(4);crypto.getRandomValues(bytes);serial=Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('').toUpperCase()}catch{serial=Date.now().toString(16).slice(-8).toUpperCase().padStart(8,'0')}state.certificate={id:'ES-'+serial,issuedAt:new Date().toISOString().slice(0,10)};return true}return false}
  const certificateRegistrations=new Set();
  async function registerCertificate(c){const status=$('#certificate-verification-status');if(!status||!supabaseClient||!currentUser)return;if(certificateRegistrations.has(c.id))return;certificateRegistrations.add(c.id);status.textContent='Mendaftarkan nomor verifikasi…';try{for(let i=0;syncBusy&&i<30;i++)await new Promise(resolve=>setTimeout(resolve,150));if(syncBusy)throw new Error('Progress is still syncing');await pushProgress();const {data,error}=await supabaseClient.from('certificate_registry').select('certificate_id').eq('certificate_id',c.id).maybeSingle();if(error)throw error;if(!data){const {error:insertError}=await supabaseClient.from('certificate_registry').insert({certificate_id:c.id,user_id:currentUser.id,recipient_name:'Michelle',course:'English for Educators',module_count:modules.length,issued_at:c.issuedAt});if(insertError)throw insertError}status.classList.add('is-verified');status.innerHTML=`Nomor sertifikat tercatat. <a href="verifikasi.html?id=${encodeURIComponent(c.id)}">Buka halaman verifikasi</a>.`}catch(error){certificateRegistrations.delete(c.id);status.classList.remove('is-verified');status.textContent='Sertifikat sudah dibuat, tetapi verifikasi publik belum aktif. Jalankan pengaturan verifikasi di Supabase terlebih dahulu.';console.error('Certificate registry failed',error)}}  function certificate(){if(ensureCertificate())save();const adminPreview=isAdmin(),c=adminPreview?null:state.certificate,done=modules.filter((_,i)=>state.completed.includes(i)).length;if(!c&&!adminPreview){$('#sertifikat').innerHTML=`<div class="intro"><span class="eyebrow">PENGAKUAN PERJALANAN BELAJAR</span><h1>Sertifikat EnglishSteps ♡</h1><p>Sertifikat penyelesaian akan terbuka setelah semua modul ditandai selesai.</p></div><div class="certificate-progress"><div class="certificate-progress-number">${done}<span> / ${modules.length}</span></div><div><b>Modul selesai</b><p>${done} modul sudah ditandai selesai. Selesaikan ${modules.length-done} modul lagi untuk membuka sertifikat.</p><div class="meter"><span style="width:${Math.round(done/modules.length*100)}%"></span></div></div></div><button class="button pink-button" data-go="belajar">Lanjutkan belajar →</button><p class="certificate-note">Sertifikat ini mengakui penyelesaian materi belajar mandiri EnglishSteps, bukan sertifikasi kompetensi atau penetapan tingkat CEFR.</p>`;return}const date=c?new Date(c.issuedAt+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}):'Pratinjau saja';const ref=c?esc(c.id):'PRATINJAU · BELUM DITERBITKAN';$('#sertifikat').innerHTML=`<div class="intro certificate-heading"><span class="eyebrow">${adminPreview?'MODE ADMIN · PRATINJAU':'PENGAKUAN PERJALANAN BELAJAR'}</span><h1>${adminPreview?'Pratinjau sertifikat':'Sertifikat EnglishSteps ♡'}</h1><p>${adminPreview?'Ini hanya contoh tampilan dan bukan sertifikat yang telah diterbitkan.':'Selamat atas konsistensi menyelesaikan seluruh jalur belajar.'}</p></div>${adminPreview?'<div class="admin-preview-banner">PRATINJAU ADMIN — belum diterbitkan dan tidak membuktikan penyelesaian Michelle.</div>':''}<article class="certificate-paper" id="certificate-print">${adminPreview?'<div class="certificate-watermark">PRATINJAU</div>':''}<div class="certificate-brand">♡ EnglishSteps</div><div class="certificate-kicker">SERTIFIKAT PENYELESAIAN PEMBELAJARAN MANDIRI</div><h2>Diberikan kepada</h2><div class="certificate-name">Michelle</div><p class="certificate-copy">telah menyelesaikan seluruh <b>${modules.length} modul</b> dalam program belajar mandiri</p><div class="certificate-course">English for Educators</div><p class="certificate-copy">sebagai bagian dari perjalanan mengembangkan bahasa Inggris untuk konteks pendidikan.</p><div class="certificate-meta"><div><small>${c?'Tanggal diterbitkan':'Status'}</small><b>${date}</b></div><div><small>ID referensi</small><b>${ref}</b></div></div><div class="certificate-signature"><span>EnglishSteps</span><small>Program belajar mandiri</small></div><p class="certificate-disclaimer">Dokumen ini merupakan pengakuan penyelesaian materi EnglishSteps. Ini bukan sertifikasi kompetensi dari lembaga terakreditasi dan tidak menetapkan level CEFR.${adminPreview?' Pratinjau admin bukan sertifikat terbit.':''}</p></article><div id="certificate-verification-status" class="verification-status" aria-live="polite"></div><div class="certificate-actions"><button class="button pink-button" type="button" data-action="print-certificate">${adminPreview?'Cetak pratinjau':'Cetak / Simpan sebagai PDF'}</button></div>`;if(c&&!adminPreview)registerCertificate(c)}
  function render(){document.querySelectorAll('.nav').forEach(x=>{const active=x.dataset.page===page;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===page));$('#streak').textContent=state.streak||0;if(page==='beranda'){home();if(isAdmin()){decorateAdminHome();decorateAdminQA()}}if(page==='asesmen')assessment();if(page==='belajar')lesson();if(page==='latihan')practice();if(page==='kamus')dictionary();if(page==='toolkit')toolkit();if(page==='progres'){progress();decorateProgress();decorateWeeklyGoal()}if(page==='sertifikat')certificate();if(page==='panduan')guide()}  function decorateAdminHome(){const root=$('#beranda'),welcome=root.querySelector('.welcome');if(!welcome)return;welcome.querySelector('.eyebrow').textContent='DASHBOARD ADMIN · PEMERIKSAAN FITUR';welcome.querySelector('h1').textContent='Halo, Faari — mode admin aktif';welcome.querySelector('p').textContent='Semua menu dan 8 modul bisa dibuka untuk memeriksa konten, tampilan, dan alur fitur.';const note=root.querySelector('.love-card');if(note)note.innerHTML='<div class="love-spark">◈</div><div class="eyebrow">PANEL PEMERIKSAAN</div><h2>Periksa EnglishSteps dari awal sampai akhir</h2><p>Akun admin memiliki pratinjau sertifikat dan akses ke seluruh halaman. Coba tiap menu, tombol, latihan, vocabulary, situasi sekolah, serta progres. Perubahan progres tersimpan pada akun yang sedang dipakai.</p><div class="admin-shortcuts"><button class="button outline" data-go="belajar">Periksa 8 modul →</button><button class="button outline" data-go="sertifikat">Pratinjau sertifikat →</button><button class="button outline" data-go="progres">Periksa progres →</button></div>';const hero=root.querySelector('.hero');if(hero){hero.querySelector('.eyebrow').textContent='KONTEN MICHELLE · MODE PRATINJAU';hero.querySelector('h2').textContent='English for educators';hero.querySelector('p').textContent='Buka jalur belajar untuk meninjau semua modul, lalu cek kuis, vocabulary, situasi sekolah, dan progres.';hero.querySelector('.button').textContent='Buka jalur belajar →';const art=hero.querySelector('.hero-art');if(art)art.textContent='🧭'}const stats=root.querySelectorAll('.stats .stat');if(stats.length>=3){stats[0].querySelector('small').textContent='Mode akun';stats[0].querySelector('strong').innerHTML='ADMIN';stats[1].querySelector('small').textContent='Akses materi';stats[1].querySelector('strong').innerHTML='8 <em>modul</em>';stats[2].querySelector('small').textContent='Sertifikat';stats[2].querySelector('strong').innerHTML='Pratinjau'}}  function decorateAdminQA(){const note=$('#beranda .love-card');if(!note)return;let saved={};try{saved=JSON.parse(localStorage.getItem('englishsteps-admin-qa-v1')||'{}')}catch{}const general=[['dashboard','Beranda dan pintasan admin','beranda'],['assessment','Asesmen: alur pertanyaan dan hasil','asesmen'],['practice','Latihan harian dan kuis','latihan'],['dictionary','Pencarian dan filter vocabulary','kamus'],['toolkit','Skenario English di sekolah','toolkit'],['progress','Ringkasan dan detail progres','progres'],['certificate','Pratinjau sertifikat admin','sertifikat'],['password-toggle','Tombol lihat/sembunyikan password',''],['mobile','Tampilan layar ponsel','beranda']];const modulesHtml=modules.map((m,i)=>`<div class="qa-row"><label><input type="checkbox" data-qa-check="module-${i}" ${saved['module-'+i]?'checked':''}><span>Modul ${i+1}: ${esc(m.title)}</span></label><button class="link" data-open-module="${i}">Buka →</button></div>`).join('');const generalHtml=general.map(([key,label,page])=>`<div class="qa-row"><label><input type="checkbox" data-qa-check="${key}" ${saved[key]?'checked':''}><span>${label}</span></label>${page?`<button class="link" data-go="${page}">Buka →</button>`:`<span class="qa-open-hint">Coba dari layar login</span>`}</div>`).join('');note.insertAdjacentHTML('beforeend',`<section class="qa-panel"><div class="qa-heading"><div><span class="eyebrow">CHECKLIST PEMERIKSAAN</span><h3>Uji fitur satu per satu</h3></div><b id="qa-count"></b></div><div class="meter qa-meter" id="qa-meter" role="progressbar" aria-label="Pemeriksaan fitur selesai"><span></span></div><details class="qa-details" open><summary>8 modul pembelajaran</summary>${modulesHtml}</details><details class="qa-details"><summary>Fitur dan tampilan lainnya</summary>${generalHtml}</details><p class="qa-help">Centang setelah kamu mencoba fitur dan memastikan hasilnya sesuai. Checklist tersimpan di browser ini, terpisah dari progres belajar.</p></section>`);updateQaCount()}
  function updateQaCount(){const checks=[...document.querySelectorAll('[data-qa-check]')];const done=checks.filter(x=>x.checked).length,total=checks.length,count=$('#qa-count'),bar=$('#qa-meter span');if(count)count.textContent=`${done} / ${total} diperiksa`;if(bar)bar.style.width=`${total?Math.round(done/total*100):0}%`}
  document.addEventListener('change',e=>{const check=e.target.closest('[data-qa-check]');if(!check||!isAdmin())return;let saved={};try{saved=JSON.parse(localStorage.getItem('englishsteps-admin-qa-v1')||'{}')}catch{}saved[check.dataset.qaCheck]=check.checked;try{localStorage.setItem('englishsteps-admin-qa-v1',JSON.stringify(saved))}catch{}updateQaCount()});
  function decorateProgress(){const root=$('#progres'),intro=root.querySelector('.intro');if(!intro)return;const next=modules.findIndex((_,i)=>!state.completed.includes(i)),done=modules.length-Math.max(next,0);const pct=Math.round((state.completed.length/modules.length)*100);const nextContent=next<0?'<b>Semua modul selesai</b><p>Jalur belajar inti sudah ditandai selesai.</p>':'<b>Langkah berikutnya</b><p>'+esc(modules[next].title)+' · '+esc(modules[next].level)+'</p><button class="button pink-button" data-open-module="'+next+'">Lanjutkan modul '+(next+1)+' →</button>';const list=modules.map((m,i)=>`<button class="progress-module ${state.completed.includes(i)?'is-done':''}" data-open-module="${i}"><span class="progress-module-number">${state.completed.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span class="progress-module-info"><b>${esc(m.title)}</b><small>${esc(m.level)} · ${state.completed.includes(i)?'Selesai':'Belum selesai'}</small></span><span class="progress-module-arrow">→</span></button>`).join('');intro.insertAdjacentHTML('afterend',`<section class="progress-roadmap"><div class="roadmap-summary"><div><span class="eyebrow">JALUR INTI</span><strong>${state.completed.length} / ${modules.length}</strong><small>modul selesai · ${pct}%</small></div><div class="roadmap-meter" role="progressbar" aria-label="Progres modul" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div><div class="roadmap-next">${nextContent}</div></div><details class="roadmap-details"><summary>Lihat status semua 8 modul</summary><div class="progress-module-grid">${list}</div></details></section>`);root.insertAdjacentHTML('beforeend',`<section class="backup-panel" aria-labelledby="backup-title"><h2 id="backup-title">Cadangan dan panduan</h2><p>Unduh cadangan progres secara berkala. Untuk memulihkan, masuk dengan akun yang sama lalu pilih file cadangan akun tersebut.</p><div class="backup-actions"><button class="button outline" type="button" data-action="backup-export">Unduh cadangan progres</button><button class="button outline" type="button" data-action="backup-restore">Pulihkan dari file</button><input id="backup-file" type="file" accept="application/json,.json" hidden aria-label="Pilih file cadangan progres"></div><details class="guide-details"><summary>Panduan singkat menggunakan EnglishSteps</summary><ol><li>Pilih <b>Jalur belajar</b>, buka modul, pelajari kartu frasa, lalu kerjakan kuis atau tandai modul selesai.</li><li>Gunakan <b>Latihan harian</b> dan <b>Kamus vocabulary</b> untuk mengulang materi.</li><li>Masuk dengan akun yang sama di perangkat lain agar progres tersinkron. Unduh cadangan sebagai salinan tambahan.</li><li>Sertifikat Michelle terbuka setelah 8 modul selesai. Nomornya bisa diperiksa di halaman verifikasi; sertifikat ini pengakuan belajar mandiri, bukan sertifikasi resmi.</li></ol></details><p id="backup-help" class="backup-help" role="status" aria-live="polite">File cadangan berisi data progres akun ini. Jangan membagikannya.</p></section>`)}  function decorateWeeklyGoal(){
    const root=$('#progres'),intro=root.querySelector('.intro');if(!intro)return;
    const goal=Math.min(7,Math.max(1,Number(state.weeklyGoal)||3));
    const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7));
    const startKey=dateKey(start),endKey=today();
    const sessions=new Set((state.history||[]).filter(item=>item&&item.date>=startKey&&item.date<=endKey).map(item=>item.date)).size;
    const pct=Math.min(100,Math.round(sessions/goal*100));
    const panel=document.createElement('section');panel.className='weekly-goal';panel.setAttribute('aria-labelledby','weekly-goal-title');
    const options=[1,2,3,4,5,6,7].map(n=>'<button type="button" class="weekly-goal-choice '+(goal===n?'is-selected':'')+'" data-action="weekly-goal" data-weekly-goal="'+n+'" aria-pressed="'+(goal===n)+'">'+n+'</button>').join('');
    panel.innerHTML='<div class="weekly-goal-top"><div><span class="eyebrow">KEBIASAAN BELAJAR</span><h2 id="weekly-goal-title">Target minggu ini</h2></div><strong>'+sessions+' / '+goal+' sesi</strong></div><div class="weekly-goal-meter" role="progressbar" aria-label="Target belajar mingguan" aria-valuenow="'+pct+'" aria-valuemin="0" aria-valuemax="100"><span style="width:'+pct+'%"></span></div><p>'+ (sessions>=goal?'Target minggu ini tercapai. Bagus, pertahankan ritmenya!':'Pilih target '+(goal===1?'yang nyaman':'antara 1–7 sesi')+' per minggu. Sesi dihitung maksimal satu kali per hari.')+'</p><div class="weekly-goal-options" role="group" aria-label="Pilih target sesi belajar per minggu">'+options+'</div>';
    intro.insertAdjacentElement('afterend',panel);
  }
  function assessment(){const labels={reading:'Membaca',listening:'Mendengar',language:'Use of English',speaking:'Berbicara',writing:'Menulis'};if(state.baseline){const b=state.baseline;$('#asesmen').innerHTML=`<div class="intro"><span class="eyebrow">${isAdmin()?'PANEL PEMERIKSAAN FAARI':'PETA KEMAMPUAN MICHELLE'}</span><h1>Snapshot kemampuan 🌷</h1><p>Latihan informal untuk menentukan fokus belajar berikutnya. Ini bukan ujian atau sertifikat Cambridge.</p></div><div class="skill-grid">${Object.entries(b.scores).map(([k,v])=>`<article class="skill-card"><div><span class="eyebrow">${labels[k]}</span><strong>${v.score}%</strong></div><div class="meter"><span style="width:${v.score}%"></span></div><small>${v.kind==='self'?'Refleksi diri':'Hasil mini-check'} · ${v.score}%</small></article>`).join('')}</div><div class="panel baseline-focus"><div class="panel-title">Fokus belajar yang disarankan</div><h2>${labels[b.focus]} 🌱</h2><p class="muted">Mulai dari latihan ${labels[b.focus].toLowerCase()} singkat dan ulangi lagi setelah beberapa minggu untuk melihat perubahan.</p><button class="button pink-button" data-go="latihan">Mulai latihan hari ini →</button><button class="button outline" data-action="assessment-restart">Ulangi asesmen</button></div><p class="muted">Asesmen terakhir: ${new Date(b.date+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}. Skor berbicara dan menulis berasal dari refleksi diri, bukan penilaian otomatis.</p>`;return}
    const groups=['reading','listening','language'];const wordCount=(state.assessmentDraft||'').trim().split(/\s+/).filter(Boolean).length;$('#asesmen').innerHTML=`<div class="intro"><span class="eyebrow">LANGKAH PERTAMA · 5–8 MENIT</span><h1>Kenali kemampuanmu, ${accountName()} ♡</h1><p>Jawab beberapa pertanyaan untuk memilih latihan yang tepat. Hasilnya hanya peta awal, bukan tes resmi atau sertifikasi Cambridge.</p></div><div class="assessment-note">🌷 <span><b>Belajar tanpa tekanan.</b> Jawab sebisamu. Bagian berbicara dan menulis memakai refleksi diri, jadi tidak ada jawaban yang “memalukan”.</span></div><div class="assessment-layout"><div class="assessment-main">${groups.map((skill,si)=>`<section class="panel assessment-section"><div class="assessment-heading"><span class="assessment-number">0${si+1}</span><div><span class="eyebrow">${labels[skill]}</span><h2>${skill==='reading'?'Baca konteks berikut':skill==='listening'?'Dengarkan kalimatnya':'Pilih penggunaan bahasa yang tepat'}</h2></div></div>${skill==='reading'?`<blockquote>${assessmentItems.find(x=>x.skill==='reading').prompt}</blockquote>`:''}${assessmentItems.map((q,i)=>q.skill===skill?`<div class="assessment-question"><p>${skill==='listening'?`<button class="button outline listen-line" data-speak="${esc(q.audio)}">🔊 Dengarkan kalimat</button><br>`:''}${esc(q.question)}</p><div class="assessment-options">${q.options.map((o,oi)=>`<button class="assessment-option ${assessmentAnswers[i]===oi?'selected':''}" data-assess-q="${i}" data-assess-option="${oi}">${esc(o)}</button>`).join('')}</div></div>`:'').join('')}</section>`).join('')}<section class="panel assessment-section"><div class="assessment-heading"><span class="assessment-number">04</span><div><span class="eyebrow">BERBICARA & MENULIS</span><h2>Refleksi kemampuan saat ini</h2></div></div><p class="muted">Pilih pernyataan yang paling mendekati pengalamanmu sekarang.</p>${[['speaking','Berbicara','Saya bisa menjelaskan ide dan berinteraksi dalam rapat berbahasa Inggris.'],['writing','Menulis','Saya bisa menulis email kerja yang jelas dengan beberapa detail.']].map(([key,title,desc])=>`<div class="rating-row"><div><b>${title}</b><small>${desc}</small></div><div class="rating-options">${['Masih sulit','Dengan bantuan','Cukup mandiri','Nyaman spontan'].map((txt,i)=>`<button class="rating ${assessmentRatings[key]===i+1?'selected':''}" data-assess-rating="${key}" data-rating="${i+1}">${i+1}<small>${txt}</small></button>`).join('')}</div></div>`).join('')}<label class="writing-label" for="assessment-writing">Contoh tulisan opsional: tulis 2–4 kalimat tentang perkembangan murid atau rencana pembelajaran.</label><textarea id="assessment-writing" placeholder="I would like to share an update about...">${esc(state.assessmentDraft||'')}</textarea><small class="word-count">${wordCount} kata · disimpan di browser ini</small></section><button class="button pink-button assessment-submit" data-action="assessment-submit">Simpan peta kemampuanku ♡</button></div><aside class="assessment-aside"><div class="panel"><div class="panel-title">Yang diperiksa</div><div class="assessment-check"><span>01</span><p><b>Reading</b><small>Memahami informasi dan maksud bacaan.</small></p></div><div class="assessment-check"><span>02</span><p><b>Listening</b><small>Menangkap informasi dari kalimat lisan.</small></p></div><div class="assessment-check"><span>03</span><p><b>Use of English</b><small>Memilih vocabulary dan tata bahasa yang wajar.</small></p></div><div class="assessment-check"><span>04</span><p><b>Speaking & Writing</b><small>Refleksi kemampuan komunikasi profesional.</small></p></div><p class="muted">Hasil mini-check membantu memilih fokus; bukan pengukuran level resmi.</p></div><button class="button outline" data-action="assessment-skip">Lewati dulu</button></aside></div>`}
  function home(){const done=state.completed.length,pct=Math.round(done/modules.length*100),date=new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long'});$('#date').textContent=date;$('#beranda').innerHTML=`<div class="welcome"><div><span class="eyebrow">LANGKAH KECIL, MASA DEPAN BESAR</span><h1>Michelle, kamu pasti bisa! ♡</h1><p>${date} · A2 sebagai titik awal · target B2 · pengayaan C1–C2.</p></div><div class="welcome-art">🌷</div></div><div class="love-card"><div class="love-spark">♡</div><div class="eyebrow">PESAN KECIL DARI AKU</div><h2>SEMANGAT BELAJAR YAA SAYANGKU, INI AKU BUATKAN WEB UNTUK SAYANG MUDAH BELAJARNYA</h2><div class="love-hearts">♡　♡　♡</div><p>Semoga setiap pelajaran bikin Michelle makin percaya diri. Aku selalu dukung kamu.</p></div>${state.baseline?`<div class="assessment-banner"><span>◎</span><div><b>Peta kemampuan tersimpan</b><small>Fokus saat ini: ${({reading:"Membaca",listening:"Mendengar",language:"Use of English",speaking:"Berbicara",writing:"Menulis"})[state.baseline.focus]}</small></div><button class="link" data-go="asesmen">Lihat hasil →</button></div>`:`<div class="assessment-banner"><span>◎</span><div><b>Mulai dengan mengenali titik awalmu</b><small>Asesmen singkat untuk memilih fokus latihan Michelle.</small></div><button class="button outline" data-go="asesmen">Mulai asesmen →</button></div>`}<div class="hero"><div><span class="eyebrow">JALUR BELAJAR MICHELLE</span><h2>English for educators</h2><p>Bangun kemampuan bertahap dari A2 ke B2, lalu lanjutkan pengayaan C1–C2 lewat komunikasi nyata di sekolah.</p><button class="button pink-button" data-go="belajar">Lanjutkan belajar <span>→</span></button></div><div class="hero-art">🌸</div></div><div class="heading"><h2>Perjalananmu</h2><button class="link" data-go="progres">Lihat progres →</button></div><div class="stats"><div class="stat"><span class="stat-icon">📚</span><div><small>Level awal</small><strong>A2 <em>→ C2</em></strong></div></div><div class="stat"><span class="stat-icon">🔥</span><div><small>Streak belajar</small><strong>${state.streak||0} <em>hari</em></strong></div></div><div class="stat"><span class="stat-icon">🌟</span><div><small>Modul selesai</small><strong>${done} <em>/ ${modules.length}</em></strong></div></div></div><div class="quick-actions"><button class="quick-action" data-go="latihan"><span>✦</span><b>Latihan harian</b><small>Ulangi & kuis</small><i>→</i></button><button class="quick-action" data-go="kamus"><span>⌕</span><b>1.000 vocabulary</b><small>Cari kata & frasa</small><i>→</i></button><button class="quick-action" data-go="toolkit"><span>▧</span><b>Situasi sekolah</b><small>Practice for Cikal</small><i>→</i></button></div><div class="lower"><div class="panel"><div class="panel-title">Jalur menuju Advanced <span style="float:right;color:#bc6190">${pct}%</span></div><div class="meter-label"><span>A2 → B1 → B2 → C1 → C2</span><span>Jalur bertahap</span></div><div class="meter"><span style="width:${Math.max(pct,4)}%"></span></div><p class="muted" style="margin:14px 0 0">${done} dari ${modules.length} modul inti selesai. Target B2 ditempuh bertahap lewat praktik rutin.</p></div><div class="panel"><div class="panel-title">Mulai dari situasi nyata</div><p class="muted">Instruksi kelas, umpan balik murid, komunikasi dengan keluarga, rapat, dan presentasi profesional.</p><button class="button outline" data-go="belajar">Lihat semua modul →</button></div></div>`}
  function practice(){const list=window.VOCABULARY,focus=list.filter(w=>w.level==="A1"||w.level==="A2");const day=Math.floor(Date.now()/86400000),offset=(day*8)%Math.max(1,focus.length),due=dueReviewWords(),daily=[...due.slice(0,10)];for(let n=0;daily.length<10&&n<focus.length;n++){const candidate=focus[(offset+n)%focus.length];if(!daily.some(x=>x.word===candidate.word)&&(!state.learned.includes(candidate.word)||!state.reviews?.[candidate.word]))daily.push(candidate)}for(let n=0;daily.length<10&&n<list.length;n++){const candidate=list[(day*10+n)%list.length];if(!daily.some(x=>x.word===candidate.word))daily.push(candidate)}dailyDeck=daily;const w=daily[practiceCard%daily.length];$('#latihan').innerHTML=`<div class="intro"><span class="eyebrow">SESI RINGKAS · 10–15 MENIT</span><h1>Latihan kecil hari ini ✦</h1><p>Fokus vocabulary A1–A2, dengarkan pengucapannya, lalu cek pemahamanmu.</p></div><div class="practice-summary"><div><span class="eyebrow">KARTU HARI INI</span><strong>${practiceCard%daily.length+1}<small> / ${daily.length}</small></strong></div><div><span class="eyebrow">SUDAH DIKUASAI</span><strong>${state.learned.length}<small> kata & frasa</small></strong></div><div class="practice-tip">🔁 ${due.length} kata perlu diulang hari ini. Ucapkan kata sebelum membalik kartu.</div></div>${practiceQuiz?practiceQuizView():`<div class="practice-layout"><div class="lesson practice-card"><div class="lesson-top"><span>VOCABULARY PICK · ${esc(w.level)}</span><span class="badge">${practiceCard%daily.length+1} / ${daily.length}</span></div><button data-practice-word="${esc(w.word)}" class="practice-flash ${practiceFlip?'is-flipped':''}" data-action="practice-flip"><span class="eyebrow">${practiceFlip?'ARTI DALAM BAHASA INDONESIA':'KOSAKATA HARI INI'}</span><strong>${esc(practiceFlip?w.meaning:w.word)}</strong><span class="tag">${practiceFlip?esc(w.category):esc(w.partOfSpeech)}</span>${practiceFlip?`<span class="practice-example">${esc(w.example)}<br><i>${esc(w.translation)}</i></span>`:'<small>Tekan kartu untuk melihat arti dan contoh</small>'}</button><div class="actions"><button class="button outline" data-speak="${esc(w.word)}">🔊 Dengarkan</button><button class="button outline" data-action="practice-flip">Balik kartu</button><button class="button pink-button" data-action="practice-known">${state.learned.includes(w.word)?'✓ Sudah dipelajari':'♡ Tandai dipahami'}</button><button class="button outline" data-action="practice-next">Berikutnya →</button></div><p class="muted practice-caption">${esc(w.example)} <span>— ${esc(w.translation)}</span></p></div><aside class="practice-aside"><div class="panel"><div class="panel-title">Cek pemahamanmu</div><p class="muted">Selesai melihat kartu? Coba kuis singkat dari 1.000 kosakata.</p><button class="button pink-button" data-action="practice-start-quiz">Mulai kuis 5 soal →</button></div><div class="panel pronunciation-panel"><div class="panel-title">🎙️ Tes pengucapan</div><p class="muted">Ucapkan <b>${esc(w.word)}</b>, lalu lihat apakah browser menangkap kata yang sama.</p><div class="pron-buttons"><button class="button pink-button" data-action="pronounce" data-pron-target="${esc(w.word)}">Mulai tes</button><button class="button outline" data-speak="${esc(w.word)}">Dengarkan contoh</button></div>${pronunciationResult&&pronunciationResult.target===w.word?`<div class="pron-result ${pronunciationResult.error?'error':''}">${pronunciationResult.error?`<b>${esc(pronunciationResult.error)}</b>`:`<b>${pronunciationResult.score}% kecocokan kata</b><p>Yang tertangkap: “${esc(pronunciationResult.transcript)}”</p><small>${pronunciationResult.score>=90?'Kata target terdengar cocok. Bagus!':pronunciationResult.score>=60?'Hampir cocok. Coba ucapkan lebih pelan dan jelas.':'Belum cocok dengan kata target. Dengarkan contoh lalu coba lagi.'}</small>`}<small class="pron-note">Skor ini membandingkan teks hasil pengenalan suara, bukan mengukur aksen atau mutu pelafalan secara pasti. Hasil dipengaruhi browser, mikrofon, dan kebisingan.</small></div>`:''}</div><div class="panel"><div class="panel-title">💗 Ingat pesan ini</div><p class="muted">Tidak harus sempurna hari ini. Satu frasa baru yang berani dipakai sudah merupakan kemajuan.</p></div></aside></div>`}`}
  function practiceQuizView(){const q=practiceQuiz.questions[practiceQuiz.at];if(practiceQuiz.finished)return `<div class="panel result"><div style="font-size:42px">${practiceQuiz.score>=4?'🌷':'💪'}</div><h2>Sesi latihan selesai!</h2><p>Skor ${accountName()}: <b>${practiceQuiz.score} / ${practiceQuiz.questions.length}</b></p><p class="muted">${practiceQuiz.score>=4?'Hebat! Kosakata ini semakin melekat.':'Kamu sudah mencoba. Ulangi kartu lalu coba lagi ya.'}</p><button class="button pink-button" data-action="practice-start-quiz">Coba kuis lagi</button></div>`;return `<div class="quiz"><div class="question"><small>QUIZ VOCABULARY · ${practiceQuiz.at+1}/${practiceQuiz.questions.length}</small><h2>${esc(q.word)}</h2><button class="sound" data-speak="${esc(q.word)}">🔊</button><p class="muted">Apa arti kata ini?</p><div class="options">${practiceQuiz.options.map(o=>`<button class="option ${practiceQuiz.selected===o?(o===q.meaning?'correct':'wrong'):''}" data-practice-option="${esc(o)}" ${practiceQuiz.selected?'disabled':''}>${esc(o)}</button>`).join('')}</div><div class="feedback">${practiceQuiz.selected?(practiceQuiz.selected===q.meaning?('✓ Betul, '+accountName()+'!'):`Belum tepat. Artinya: ${esc(q.meaning)}`):''}</div>${practiceQuiz.selected?`<button class="button pink-button" data-action="practice-quiz-next">${practiceQuiz.at===practiceQuiz.questions.length-1?'Lihat hasil':'Lanjut →'}</button>`:''}</div></div>`}
  const scenarios=[{title:'Memberi instruksi di kelas',label:'CLASSROOM · A2–B1',prompt:'Minta murid membuka buku, bekerja berpasangan, lalu memberi tahu kamu jika sudah selesai.',lines:[['Please open your books to page ten.','Silakan buka buku kalian di halaman sepuluh.'],['Work in pairs and compare your answers.','Bekerjalah berpasangan dan bandingkan jawaban kalian.'],['Let me know when you are ready.','Beri tahu saya jika kalian sudah siap.']]},{title:'Menyampaikan perkembangan murid',label:'FAMILY COMMUNICATION · B1–B2',prompt:'Sampaikan satu hal positif, satu area yang sedang dikembangkan, dan ajak orang tua bekerja sama.',lines:[['I’d like to share an update on Maya’s progress.','Saya ingin menyampaikan perkembangan Maya.'],['She has become more confident when sharing her ideas.','Ia semakin percaya diri saat membagikan ide.'],['We can work together to support her next steps.','Kita bisa bekerja sama untuk mendukung langkah berikutnya.']]},{title:'Berpendapat dalam rapat',label:'TEAM MEETING · B2',prompt:'Tanggapi ide rekan kerja dengan sopan, tambahkan sudut pandang, lalu ajukan tindak lanjut.',lines:[['That’s a helpful point. I’d like to build on it.','Itu masukan yang membantu. Saya ingin menambahkan hal tersebut.'],['From my perspective, the routine is working well.','Dari sudut pandang saya, rutinitas ini berjalan baik.'],['Could we agree on a follow-up action for next week?','Bisakah kita menyepakati tindak lanjut untuk minggu depan?']]},{title:'Menulis email profesional',label:'PROFESSIONAL WRITING · B2',prompt:'Buka email dengan sopan, jelaskan tujuan, lalu akhiri dengan permintaan tindak lanjut yang jelas.',lines:[['I hope you’re doing well.','Semoga Anda dalam keadaan baik.'],['I’m writing to follow up on our discussion.','Saya menulis untuk menindaklanjuti diskusi kita.'],['Please let me know if you have any questions.','Silakan beri tahu saya jika ada pertanyaan.']]},{title:'Rapat guru dan koordinasi tim',label:'TEACHER MEETING · A2–B1',prompt:'Sampaikan pengamatan singkat, usulkan dukungan untuk murid, lalu sepakati siapa melakukan apa dan kapan ditinjau kembali.',lines:[['I noticed that a few students need more time to begin the task.','Saya melihat beberapa murid membutuhkan lebih banyak waktu untuk mulai mengerjakan tugas.'],['Could we try the visual checklist this week?','Bisakah kita mencoba daftar periksa visual minggu ini?'],['Let’s review how it works at our next meeting.','Mari tinjau hasilnya di rapat berikutnya.']]},{title:'Komunikasi dengan orang tua',label:'PARENT CONVERSATION · A2–B1',prompt:'Mulai dengan kekuatan murid, sampaikan pengamatan dengan contoh, lalu ajak keluarga menyepakati dukungan sederhana.',lines:[['I’d like to share something your child is doing well.','Saya ingin menyampaikan hal yang sudah dilakukan anak Anda dengan baik.'],['I’ve noticed that she is more willing to share her ideas.','Saya melihat ia semakin bersedia membagikan idenya.'],['What have you noticed at home?','Apa yang Anda amati di rumah?'],['We can agree on one small next step together.','Kita bisa menyepakati satu langkah kecil berikutnya bersama-sama.']]},{title:'Menulis laporan perkembangan murid',label:'STUDENT PROGRESS REPORT · A2–B1',prompt:'Susun laporan singkat: sebutkan kekuatan, bukti kemajuan, sasaran berikutnya, dan dukungan yang dapat dilakukan bersama.',lines:[['Maya is becoming more confident when speaking in a small group.','Maya semakin percaya diri saat berbicara dalam kelompok kecil.'],['She can now explain her ideas using two or three details.','Ia kini dapat menjelaskan idenya dengan dua atau tiga detail.'],['Her next goal is to organise those details in a clear order.','Sasaran berikutnya adalah menyusun detail tersebut dengan urutan yang jelas.'],['At home, regular reading together may help her build this skill.','Di rumah, membaca bersama secara rutin dapat membantunya mengembangkan kemampuan ini.']]},{title:'Membahas kebutuhan dan tindak lanjut',label:'STUDENT SUPPORT · B1',prompt:'Jelaskan kebutuhan belajar tanpa memberi label pada murid, minta perspektif rekan, dan rangkum tindak lanjut yang dapat diamati.',lines:[['What support has helped the student participate so far?','Dukungan apa yang sejauh ini membantu murid berpartisipasi?'],['Let’s record what we observe over the next two weeks.','Mari catat hal yang kita amati selama dua minggu ke depan.'],['We can adjust the plan after we review the evidence.','Kita dapat menyesuaikan rencana setelah meninjau bukti.']]}];
  function toolkit(){const active=Number(document.querySelector('#toolkit')?.dataset.scenario||0);$('#toolkit').innerHTML=`<div class="intro"><span class="eyebrow">ENGLISH FOR EDUCATORS · CICAK SERPONG</span><h1>Bahasa Inggris di sekolah 🌷</h1><p>Latih ungkapan yang bisa langsung Michelle gunakan dalam keseharian sebagai guru.</p></div><div class="scenario-grid">${scenarios.map((s,i)=>`<button class="scenario-tile ${i===active?'selected':''}" data-scenario="${i}"><span>${String(i+1).padStart(2,'0')}</span><div><small>${s.label}</small><h3>${s.title}</h3></div><b>→</b></button>`).join('')}</div><div class="scenario-detail"><div><span class="eyebrow">SIMULASI SITUASI</span><h2>${scenarios[active].title}</h2><p>${scenarios[active].prompt}</p></div><div class="scenario-lines">${scenarios[active].lines.map(([en,id])=>`<article><div><strong>${esc(en)}</strong><p>${esc(id)}</p></div><button class="icon" aria-label="Dengarkan" data-speak="${esc(en)}">🔊</button></article>`).join('')}</div><div class="scenario-challenge"><div><span class="eyebrow">YOUR TURN · LATIHAN TERPADU</span><h3>Coba jawab dengan kata-katamu sendiri</h3><p>${scenarios[active].prompt}</p></div><div class="scenario-challenge-actions"><button class="button outline" data-speak="${esc(scenarios[active].prompt)}">🔊 Dengarkan instruksi</button><button class="button outline" data-action="scenario-speak" data-scenario="${active}">🎙️ Jawab dengan suara</button></div><textarea data-scenario-answer="${active}" placeholder="Tulis jawabanmu di sini. Kamu boleh memakai contoh sebagai inspirasi.">${esc(state.scenarioAnswers?.[active]||'')}</textarea><small class="muted">Respons tersimpan di browser ini. Setelah mencoba, beri tanda latihan dan refleksikan kalimat mana yang ingin kamu kuasai.</small></div><div class="scenario-actions"><button class="button outline" data-action="scenario-copy" data-scenario="${active}">Salin contoh kalimat</button><button class="button pink-button" data-action="scenario-done" data-scenario="${active}">✓ Simpan & tandai latihan</button></div></div>`;$('#toolkit').dataset.scenario=active}
  function lesson(){const m=modules[current];$('#belajar').innerHTML=`<div class="intro"><span class="eyebrow">JALUR BELAJAR · MODUL ${current+1} DARI ${modules.length}</span><h1>${esc(m.title)} ✨</h1><p>${esc(m.focus)}</p><div class="can-do"><b>🎯 I can…</b><span>${esc(m.canDo)}</span></div></div><div class="module-strip">${modules.map((x,i)=>`<button class="module-chip ${i===current?'selected':''} ${state.completed.includes(i)?'done':''}" data-module="${i}"><span>${state.completed.includes(i)?'✓':String(i+1).padStart(2,'0')}</span>${esc(x.level)}</button>`).join('')}</div>${quiz?quizView():`<div class="study-layout"><div class="lesson"><div class="lesson-top"><span>PHRASE CARD · ${esc(m.level)}</span><span class="badge">${card+1} / ${m.items.length}</span></div><div class="flash ${flipped?'is-flipped':''}" id="flash"><span class="eyebrow">${flipped?'ARTI & CONTOH':'PHRASE FOR YOUR CLASSROOM'}</span><h2>${esc(flipped?m.items[card][1]:m.items[card][0])}</h2><button class="sound" data-speak="${esc(m.items[card][0])}" aria-label="Dengarkan">🔊</button>${flipped?`<p class="example">${esc(m.items[card][2])}<br><span class="muted">${esc(m.items[card][3])}</span></p>`:`<p class="hint">Coba ucapkan, lalu balik kartu untuk melihat arti dan contoh.</p>`}</div><div class="actions"><button class="button outline" data-action="flip">${flipped?'Lihat phrase':'Balik kartu'}</button>${flipped?`<button class="button pink-button" data-action="learned">♡ Tandai dipahami</button>`:''}<button class="button outline" data-action="next">Berikutnya →</button></div><div class="actions"><button class="link" data-action="quiz">✦ Kuis modul ini</button><button class="link" data-action="complete">Tandai modul selesai ✓</button></div></div><aside class="sidefacts"><div class="panel"><div class="panel-title">🎯 Fokus praktik</div><p class="muted">${esc(m.goal)}</p></div><div class="panel"><div class="panel-title">Michelle’s teaching phrase</div><b>${esc(m.items[(card+1)%m.items.length][0])}</b><p class="muted" style="margin:7px 0 0">${esc(m.items[(card+1)%m.items.length][1])}</p></div><div class="panel"><div class="panel-title">Level modul</div><span class="badge">${esc(m.level)}</span><p class="muted" style="margin:10px 0 0">Dengarkan pelafalan, baca contoh, lalu coba gunakan dengan konteks kelasmu.</p></div></aside></div>`}`}
  function quizView(){const m=modules[current];if(quiz.finished)return `<div class="panel result"><div style="font-size:42px">${quiz.score>=4?'🌷':'💪'}</div><h2>Kuis selesai!</h2><p>Skor ${accountName()}: <b>${quiz.score} / ${quiz.questions.length}</b></p><p class="muted">${quiz.score>=4?'Keren! Phrase ini sudah makin melekat.':'Bagus sudah mencoba. Ulangi kartu dan coba lagi, ya.'}</p><button class="button pink-button" data-action="quiz-again">Ulangi kuis</button> <button class="button outline" data-action="quiz-exit">Kembali ke modul</button></div>`;const q=quiz.questions[quiz.at],opts=quiz.options;return `<div class="quiz"><div class="question"><small>KUIS MODUL ${current+1} · ${quiz.at+1}/${quiz.questions.length}</small><h2>${esc(q[0])}</h2><p class="muted">Pilih arti yang paling tepat.</p><button class="sound" data-speak="${esc(q[0])}">🔊</button><div class="options">${opts.map(o=>`<button class="option ${quiz.selected===o?(o===q[1]?'correct':'wrong'):''}" data-option="${esc(o)}" ${quiz.selected?'disabled':''}>${esc(o)}</button>`).join('')}</div><div class="feedback">${quiz.selected?(quiz.selected===q[1]?('✓ Betul, '+accountName()+'!'):`Belum tepat. Jawaban yang benar: ${esc(q[1])}`):''}</div>${quiz.selected?`<button class="button pink-button" data-action="quiz-next">${quiz.at===quiz.questions.length-1?'Lihat hasil':'Lanjut →'}</button>`:''}</div></div>`}
  function dictionary(){const q=($('#dict-search')?.value||'').toLowerCase().trim(),status=$('#dict-status')?.value||'all',level=$('#dict-level')?.value||'all';const custom=modules.flatMap((m,mi)=>m.items.map(i=>({word:i[0],meaning:i[1],partOfSpeech:'useful phrase',category:m.title,level:m.level,example:i[2],translation:i[3],module:mi})));const all=[...custom,...window.VOCABULARY.map(x=>({...x,module:-1}))];const filtered=all.filter(w=>(!q||w.word.toLowerCase().includes(q)||w.meaning.toLowerCase().includes(q))&&(level==='all'||(level==='A1-A2'?(w.level==='A1'||w.level==='A2'):w.level.includes(level)))&&(status==='all'||(status==='learned'?state.learned.includes(w.word):!state.learned.includes(w.word))));$('#kamus').innerHTML=`<div class="intro"><span class="eyebrow">${isAdmin()?'KAMUS · PEMERIKSAAN ADMIN':'KAMUS MICHELLE'}</span><h1>English for your school day</h1><p>Cari vocabulary umum dan ungkapan profesional untuk konteks sekolah.</p></div><div class="tools"><label class="search"><span>⌕</span><input id="dict-search" placeholder="Cari phrase atau arti..." value="${esc(q)}"></label><select id="dict-level"><option value="all" ${level==='all'?'selected':''}>Semua level</option><option value="A1-A2" ${level==='A1-A2'?'selected':''}>Fokus A1–A2</option>${['A0','A1','A2','B1','B2','C1','C2'].map(x=>`<option value="${x}" ${level===x?'selected':''}>${x}</option>`).join('')}</select><select id="dict-status"><option value="all" ${status==='all'?'selected':''}>Semua status</option><option value="learned" ${status==='learned'?'selected':''}>Sudah dipelajari</option><option value="new" ${status==='new'?'selected':''}>Belum dipelajari</option></select></div><div class="results"><span>${filtered.length} hasil ditampilkan · ${window.VOCABULARY.length} vocabulary umum + ${custom.length} frasa sekolah</span><span>${state.learned.length} dipelajari</span></div><div class="word-list">${filtered.map(w=>`<article class="word"><span class="word-symbol">${w.module>=0?'♡':'✦'}</span><div class="word-content"><h3>${esc(w.word)} <button class="icon" data-speak="${esc(w.word)}">🔊</button></h3><p>${esc(w.meaning)}</p><div class="meta"><span class="tag">${esc(w.level)}</span><span class="tag">${esc(w.module>=0?'school phrase':w.category)}</span></div><details><summary>Contoh kalimat</summary><p>${esc(w.example)}<br><span class="muted">${esc(w.translation)}</span></p></details></div><div class="word-actions"><button class="icon" data-word="${esc(w.word)}">${state.learned.includes(w.word)?'✓':'＋'}</button><small>${state.learned.includes(w.word)?'Dipahami':'Belum'}</small></div></article>`).join('')||'<div class="empty">Kata belum ditemukan. Coba pencarian lain.</div>'}</div>`}
  function guide(){const admin=isAdmin();$('#panduan').innerHTML=`<div class="intro"><span class="eyebrow">PUSAT BANTUAN ENGLISHSTEPS</span><h1>Panduan singkat ♡</h1><p>${admin?'Langkah untuk meninjau fitur sebagai admin.':'Ikuti langkah kecil ini untuk belajar dan menjaga progresmu tetap aman.'}</p></div><section class="guide-welcome"><div class="guide-welcome-icon" aria-hidden="true">${admin?'🧭':'🌷'}</div><div><b>${admin?'Mode admin':'Mulai belajar'}</b><p>${admin?'Akun admin bisa membuka seluruh menu dan melihat pratinjau sertifikat. Pratinjau tidak menerbitkan sertifikat Michelle dan progres akun admin terpisah.':'Belajar santai dan berurutan. Progres belajar disimpan pada akun yang sedang digunakan.'}</p></div></section><div class="guide-grid"><article class="panel guide-card"><span class="guide-step">01</span><div><h2>Mulai dari titik awal</h2><p>Kerjakan <b>Peta kemampuan</b> bila ingin tahu latihan mana yang sebaiknya diprioritaskan. Hasilnya hanya panduan informal.</p><button class="button outline" data-go="asesmen">${admin?'Periksa asesmen':'Buka peta kemampuan'} →</button></div></article><article class="panel guide-card"><span class="guide-step">02</span><div><h2>Belajar satu modul</h2><p>Buka <b>Jalur belajar</b>, pilih modul, pelajari kartu frasa, dengarkan contoh, lalu coba kuis. Tandai selesai setelah materi dipelajari.</p><button class="button pink-button" data-go="belajar">${admin?'Periksa modul':'Lanjutkan belajar'} →</button></div></article><article class="panel guide-card"><span class="guide-step">03</span><div><h2>Ulangi sedikit setiap hari</h2><p>Pakai <b>Latihan harian</b> dan <b>Kamus vocabulary</b> untuk mengingat kata. Di halaman <b>Progres belajar</b>, atur target sesi mingguan dan lihat riwayatmu.</p><div class="guide-actions"><button class="button outline" data-go="latihan">Latihan harian →</button><button class="button outline" data-go="progres">Lihat progres →</button></div></div></article><article class="panel guide-card"><span class="guide-step">04</span><div><h2>Lihat sertifikat</h2><p>${admin?'Gunakan halaman Sertifikat untuk melihat pratinjau ber-watermark. Itu bukan sertifikat terbit.':'Sertifikat penyelesaian terbuka setelah semua 8 modul ditandai selesai. Kamu bisa mencetaknya atau menyimpan sebagai PDF.'} Sertifikat ini adalah pengakuan pembelajaran mandiri, bukan sertifikasi resmi atau penetapan level CEFR.</p><button class="button outline" data-go="sertifikat">${admin?'Buka pratinjau':'Cek sertifikat'} →</button></div></article></div><section class="panel guide-sync"><div><span class="eyebrow">SIMPAN & PULIHKAN</span><h2>Jaga progres tetap aman</h2><p>Masuk lagi dengan akun yang sama agar progres tersinkron. Periksa indikator sinkronisasi di bagian atas. Untuk salinan tambahan atau pemulihan data, buka <b>Progres belajar → Cadangan dan panduan</b>. File cadangan bersifat pribadi; simpan dengan aman dan jangan dibagikan.</p></div><button class="button outline" data-go="progres">Buka cadangan progres →</button></section><p class="guide-privacy">Pastikan kamu memakai akun yang sesuai: akun Michelle untuk belajar; akun admin untuk meninjau tampilan dan fitur. Jangan bagikan password atau file cadangan.</p>`}  function exportProgressBackup(){if(!currentUser){toast('Masuk dahulu untuk mencadangkan progres.');return}const bundle={format:'EnglishSteps-progress-backup',version:1,ownerId:currentUser.id,exportedAt:new Date().toISOString(),progress:state};const blob=new Blob([JSON.stringify(bundle,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`EnglishSteps-backup-${today()}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Cadangan progres berhasil diunduh. Simpan file dengan aman.')}
  async function importProgressBackup(file){try{if(!currentUser)throw new Error('Masuk dahulu ke akun yang sama.');const bundle=JSON.parse(await file.text());if(bundle.format!=='EnglishSteps-progress-backup'||bundle.version!==1||bundle.ownerId!==currentUser.id)throw new Error('File bukan cadangan akun ini atau formatnya tidak dikenali.');const restored=bundle.progress;if(!restored||!Array.isArray(restored.completed)||!Array.isArray(restored.learned)||!Array.isArray(restored.history))throw new Error('Isi cadangan tidak lengkap.');if(!window.confirm('Pemulihan akan mengganti progres saat ini pada akun ini. Pastikan file cadangan benar. Jika ingin menjaga progres sekarang, unduh cadangan terlebih dahulu. Lanjutkan?'))return;state={...defaultState,...restored,completed:[...new Set(restored.completed.filter(i=>Number.isInteger(i)&&i>=0&&i<modules.length))],learned:restored.learned.filter(x=>typeof x==='string').slice(0,20000),history:restored.history.filter(x=>x&&typeof x.date==='string').slice(-500)};save();await pushProgress();render();toast('Cadangan dipulihkan dan disinkronkan ke akun ini.')}catch(error){toast(error.message||'File cadangan belum bisa dipulihkan.');console.error('Progress restore failed',error)}finally{$('#backup-file').value=''}}
  document.addEventListener('change',e=>{if(e.target.id==='backup-file'&&e.target.files?.[0])importProgressBackup(e.target.files[0])});  function progress(){const mastered=window.VOCABULARY.filter(w=>state.learned.includes(w.word)).length,done=state.completed.length,pct=Math.round(done/modules.length*100);$('#progres').innerHTML=`<div class="intro"><span class="eyebrow">${isAdmin()?'RINGKASAN ADMIN · FAARI':'PROGRES MICHELLE'}</span><h1>${isAdmin()?'Ringkasan akunmu, Faari 🧭':'Setiap langkah berarti 🌷'}</h1><p>${isAdmin()?'Ringkasan ini hanya menampilkan progres akun admin dan terpisah dari akun Michelle.':'Perjalanan dari A2 menuju target B2, dengan pengayaan sampai C2.'}</p></div><div class="progress-layout"><div class="panel"><div class="panel-title">Kosakata dikuasai</div><div class="big-progress"><div class="circle" style="--value:${Math.min(100,Math.round(mastered/window.VOCABULARY.length*100))*3.6}deg"><span>${Math.min(100,Math.round(mastered/window.VOCABULARY.length*100))}%</span></div><div><h2>${mastered} / ${window.VOCABULARY.length} kata</h2><p class="muted">Terus ulangi kata sedikit demi sedikit.</p></div></div><div class="meter" style="margin-top:18px"><span style="width:${Math.max(2,Math.min(100,mastered/window.VOCABULARY.length*100))}%"></span></div></div><div class="panel"><div class="panel-title">Pengulangan terjadwal</div><h2>${dueReviewWords().length} kata perlu diulang</h2><p class="muted">Jawaban kuis menentukan kapan kata muncul lagi.</p><button class="button outline" data-go="latihan">Buka kartu hari ini →</button></div><div class="panel"><div class="panel-title">Jalur belajar inti</div><div class="big-progress"><div class="circle" style="--value:${pct*3.6}deg"><span>${pct}%</span></div><div><h2>${done} / ${modules.length} modul</h2><p class="muted">Level mulai A2<br>Tahapan sampai pengayaan C2</p></div></div><div class="meter" style="margin-top:18px"><span style="width:${Math.max(3,pct)}%"></span></div><p class="muted">C1 dan C2 menjadi pengayaan jangka panjang; progres modul tidak otomatis menyatakan level CEFR.</p></div><div class="panel"><div class="panel-title">Kebiasaan belajar</div><h2>${state.streak||0} 🔥 hari</h2><p class="muted">Belajar hari ini untuk menjaga ritme kecilmu.</p><button class="button pink-button" data-go="belajar">Lanjutkan belajar →</button></div><div class="panel"><div class="panel-title">Modul pembelajaran</div><div class="history">${modules.map((m,i)=>`<div><span>${i+1}. ${esc(m.title)}</span><span>${state.completed.includes(i)?'✓ selesai':m.level}</span></div>`).join('')}</div></div><div class="panel"><div class="panel-title">Riwayat belajar</div><div class="history">${state.history.slice(-8).reverse().map(x=>`<div><span>${new Date(x.date+'T12:00:00').toLocaleDateString('id-ID',{weekday:'short',day:'numeric',month:'short'})}</span><span>${esc(modules[x.unit]?.title||'Belajar')}</span></div>`).join('')||'<p class="muted">Aktivitas belajarmu akan muncul di sini.</p>'}</div></div></div>`}
